import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

// ================= STYLE =================
const themeStyle = `
  .chart-scroll {
    overflow-x: auto;
    overflow-y: hidden;
  }

  .history-header {
    background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
    border-radius: 8px 8px 0 0 !important;
    padding: 20px !important;
  }

  .history-header .card-title {
    color: white !important;
    margin: 0 !important;
    font-weight: bold;
    font-size: 1.25rem;
  }

  .form-select {
    border-radius: 12px !important; 
    padding: 10px 18px !important;
    border: 1px solid #e9ecef !important;
    box-shadow: 0 1px 3px rgba(0, 0, 0, .08) !important;
  }

  .form-label {
    font-weight: 700;
    color: #5e72e4;
    text-transform: uppercase;
    font-size: 0.75rem;
    margin-bottom: 8px;
  }

  .card {
    border: none !important;
    box-shadow: 0 0 2rem 0 rgba(136, 152, 170, .15) !important;
    border-radius: 0.75rem !important;
  }
`;

// ================= FILTER นาทีที่ > 20 =================
const filterOverThreshold = (labels, series, threshold = 20) => {
  const newLabels = [];
  const newSeries = [];

  labels.forEach((label, idx) => {
    if (series[idx] > threshold) {
      newLabels.push(label);
      newSeries.push(series[idx]);
    }
  });

  return { labels: newLabels, series: newSeries };
};

const CAMERA_MAP = {
  CAM01: "วิศวะ",
  CAM02: "วิทยาศาสตร์",
  CAM03: "ศิลปศาสตร์",
  CAM04: "PKY",
};

function History() {
  const currentYearCE = new Date().getFullYear();
  const currentYearBE = currentYearCE + 543;

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState(
    (new Date().getMonth() + 1).toString().padStart(2, "0")
  );
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [loading, setLoading] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" },
    { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" },
    { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" },
    { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" },
    { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" },
    { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" },
    { val: "12", name: "ธันวาคม" },
  ];

  const yearsBE = Array.from({ length: 2 }, (_, i) =>
    (currentYearBE - i).toString()
  );
  const daysArray = Array.from({ length: 31 }, (_, i) =>
    (i + 1).toString()
  );

  const timeOptions = [];
  for (let h = 7; h <= 22; h++) {
    timeOptions.push(`${h.toString().padStart(2, "0")}:00`);
  }

  // ================= FETCH DATA =================
  const handleSearch = async () => {
    setLoading(true);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(
      2,
      "0"
    )}`;
    const API_BASE = "http://localhost:3001";

    try {
      const res = await fetch(
        `${API_BASE}/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await res.json();

      if (result && result.labels && result.series) {
        // 🔴 กรองเฉพาะนาทีที่เกิน 20 คน
        const filtered = filterOverThreshold(
          result.labels,
          result.series[0],
          20
        );

        setChartState({
          labels: filtered.labels,
          series: [filtered.series],
        });
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [selectedDay, selectedMonth, selectedYearBE, startTime, endTime, cameraId]);

  // ================= CHART =================
  const barChartOptions = {
    height: "400px",
    axisX: { showGrid: false, offset: 60 },
    axisY: { onlyInteger: true, low: 0 },
    fullWidth: true,
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      data.element.attr({
        style: "stroke: #f5365c; stroke-width: 30px;",
      });

      data.group
        .elem("text", {
          x: data.x2,
          y: data.y2 - 15,
          style:
            "font-size:14px;fill:#f5365c;font-weight:bold;text-anchor:middle",
        })
        .text(data.value.y);
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>

      {/* ===== FILTER ===== */}
      <Row>
        <Col md="12">
          <Card>
            <Card.Header className="history-header">
              <Card.Title as="h4">ค้นหาข้อมูลย้อนหลัง</Card.Title>
            </Card.Header>
            <Card.Body>
              <Row className="g-3">
                <Col md="3">
                  <Form.Label className="form-label">เลือกป้าย</Form.Label>
                  <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                    <option value="CAM01">วิศวะ</option>
                    <option value="CAM02">วิทยาศาสตร์</option>
                    <option value="CAM03">ศิลปศาสตร์</option>
                    <option value="CAM04">PKY</option>
                  </Form.Select>
                </Col>

                <Col md="4">
                  <Form.Label className="form-label">วันที่</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>
                      {daysArray.map((d) => (
                        <option key={d}>{d}</option>
                      ))}
                    </Form.Select>
                    <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>
                      {monthsThai.map((m) => (
                        <option key={m.val} value={m.val}>
                          {m.name}
                        </option>
                      ))}
                    </Form.Select>
                    <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map((y) => (
                        <option key={y}>{y}</option>
                      ))}
                    </Form.Select>
                  </div>
                </Col>

                <Col md="5">
                  <Form.Label className="form-label">ช่วงเวลา</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={startTime} onChange={(e) => setStartTime(e.target.value)}>
                      {timeOptions.map((t) => (
                        <option key={t}>{t}</option>
                      ))}
                    </Form.Select>
                    <Form.Select value={endTime} onChange={(e) => setEndTime(e.target.value)}>
                      {timeOptions.map((t) => (
                        <option key={t}>{t}</option>
                      ))}
                    </Form.Select>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* ===== CHART ===== */}
      {chartState.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header className="bg-transparent border-0">
                <h6 className="text-muted">🔴 แสดงเฉพาะช่วงที่มีผู้โดยสารมากกว่า 20 คน</h6>
                <h4>กราฟสถิติ : {CAMERA_MAP[cameraId]}</h4>
              </Card.Header>
              <Card.Body>
                <div className="chart-scroll">
                  <div style={{ width: Math.max(chartState.labels.length * 60, 600) }}>
                    <ChartistGraph
                      data={chartState}
                      type="Bar"
                      options={barChartOptions}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
